from typing import Protocol


class ObjectStorage(Protocol):
    def put(self, key: str, content: bytes, *, timeout: float) -> str: ...


def upload(key: str, content: bytes, *, storage: ObjectStorage) -> str:
    return storage.put(key, content, timeout=30)

