import sqlite3
from datetime import datetime


class SqliteFeedingRepository:
    def __init__(self, path: str) -> None:
        self._connection = sqlite3.connect(path)

    def add(self, tank_id: str, grams: int, fed_at: datetime) -> None:
        with self._connection:
            self._connection.execute(
                "INSERT INTO feedings VALUES (?, ?, ?)", (tank_id, grams, fed_at.isoformat())
            )

