from enum import StrEnum
from typing import Final

_EXTRA_MIN_DIAMETER_MM: Final = 70


class Grade(StrEnum):
    EXTRA = "extra"
    FIRST = "first"
    SECOND = "second"


def grade(diameter_mm: int, *, blemished: bool) -> Grade:
    if blemished:
        return Grade.SECOND
    if diameter_mm >= _EXTRA_MIN_DIAMETER_MM:
        return Grade.EXTRA
    return Grade.FIRST
